<script setup lang="ts">
import { ref } from "vue"; import { useRouter } from "vue-router"; import { ElMessage } from "element-plus"; import { queryApi } from "../api/ops"; import type { SessionItem } from "../types";
const router=useRouter(); const rows=ref<SessionItem[]>([]); const loading=ref(false); const renameItem=ref<SessionItem|null>(null); const renameTitle=ref(""); const deleteItem=ref<SessionItem|null>(null);
async function load(){loading.value=true;try{rows.value=await queryApi.sessions()}finally{loading.value=false}}void load();
async function rename(){if(!renameItem.value)return;try{await queryApi.renameSession(renameItem.value.session_id,renameTitle.value);ElMessage.success("会话名称已更新");renameItem.value=null;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:"重命名失败")}}
async function remove(){if(!deleteItem.value)return;try{await queryApi.deleteSession(deleteItem.value.session_id);ElMessage.success("会话已删除");deleteItem.value=null;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:"删除失败")}}
</script><template><el-card class="page-card" header="会话历史"><el-table v-loading="loading" :data="rows"><el-table-column prop="title" label="主题" min-width="240" show-overflow-tooltip/><el-table-column prop="updated_at" label="更新时间" width="220"/><el-table-column label="操作" width="240"><template #default="s"><el-button link @click="router.push('/chat?session='+s.row.session_id)">查看会话</el-button><el-button link @click="renameItem=s.row;renameTitle=s.row.title">重命名</el-button><el-button link type="danger" @click="deleteItem=s.row">删除</el-button></template></el-table-column></el-table><el-dialog :model-value="Boolean(renameItem)" title="重命名会话" @close="renameItem=null"><el-input v-model="renameTitle" maxlength="255"/><template #footer><el-button @click="renameItem=null">取消</el-button><el-button type="primary" @click="rename">保存</el-button></template></el-dialog><el-dialog :model-value="Boolean(deleteItem)" title="删除会话" @close="deleteItem=null"><p>该会话的消息和引用将一并删除，且不可恢复。</p><template #footer><el-button @click="deleteItem=null">取消</el-button><el-button type="danger" @click="remove">删除</el-button></template></el-dialog></el-card></template>
